{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Olcegepant, a peptide-like CGRP antagonist, has absolute oral bioavailability <1% in humans, demonstrating that peptide-like molecules with high polarity and multiple hydrogen-bonding groups can have negligible oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Plecanatide, a peptide, exhibits negligible systemic availability after oral administration in humans, directly supporting low oral bioavailability for large peptide-based structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Octreotide, a cyclic octapeptide, has absolute oral bioavailability of 0.6 ± 0.4% in healthy volunteers, providing direct peptide evidence for F < 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "A hexapeptide (HEX) has oral bioavailability of 0.3 ± 0.1% in humans, reinforcing that peptide-sized molecules with many H-bond donors and acceptors are poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "CGP 38 560, a peptidomimetic renin inhibitor, has <1% oral bioavailability in humans at 200 mg p.o., supporting low F for peptide-like query structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Aliskiren, a smaller and less polar renin inhibitor than the query, has only 2.6% absolute oral bioavailability in healthy subjects, indicating that even more drug-like molecules fail to reach 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "CDP323, a prodrug, reached 14% oral bioavailability in humans, the highest among the analogues but still below the 20% threshold, supporting the low prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an extremely large, highly polar peptide conjugate with physicochemical properties far outside oral drug space. All high-transfer experimental analogues—peptides, peptidomimetics, and small polar drugs—show absolute oral bioavailability well below 20% in humans (0.3–14%). Therefore, F >= 20% is not supported; predict low.",
  "evidence_gaps": [
    "No direct oral bioavailability experiment on the query molecule; extrapolation relies on high-transfer analogues.",
    "Fasted-state condition is not explicitly reported for most analogue records, but the magnitude of the low-F effect makes this unlikely to change the conclusion.",
    "No formulation or prodrug strategy data for the query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

